+///|
+fn diagnostic_previous_loss(source : Json) -> Json {
+  let event = diagnostic_recording_event("degraded", "previous_run_unflushed")
+  set_field(event, "missingRange", Json::string("unknown"))
+  if field(source, "affectedRunId") != Some(Json::string("unknown")) &&
+    field(source, "runId") is Some(Json::String(id)) &&
+    id.length() > 0 &&
+    id.length() <= 80 &&
+    id.iter().all(c => (c >= '0' && c <= '9') || c == '_') {
+    set_field(event, "runId", Json::string(id))
+  } else {
+    set_field(event, "affectedRunId", Json::string("unknown"))
+  }
+  for name in ["missingFromTime", "missingThroughTime"] {
+    if field(source, name) is Some(Json::String(value)) &&
+      value.length() > 0 &&
+      value.length() <= 25 &&
+      value.iter().all(c => c >= '0' && c <= '9') {
+      set_field(event, name, Json::string(value))
+    }
+  }
+  if field(event, "missingFromTime") is Some(_) &&
+    field(event, "missingThroughTime") is Some(_) {
+    set_field(event, "missingRange", Json::string("observed"))
+  }
+  let reason = field(source, "previousReason").unwrap_or(
+    field(source, "reason").unwrap_or(Json::null()),
+  )
+  if reason is Json::String(value) &&
+    [
+      "lock_busy", "invalid_lock", "invalid_store", "store_timeout", "store_unavailable",
+      "buffer_full", "protected_values_unavailable", "workspace_recording_unknown",
+    ].contains(value) {
+    set_field(event, "previousReason", reason)
+  }
+  event
+}
