 53	async fn publish_diagnostic_health() -> Unit {
 54	  guard @env.args() is [_, "--supervisor", ..] else { return }
 55	  @async.with_timeout(10, async fn() {
 56	    let directory = adapter_state_home()
 57	    let path = directory + "/diagnostic-health.json"
 58	    if !diagnostic_recording_health.incident &&
 59	      diagnostic_recording_health.dropped == 0 {
 60	      @fs.remove(path) catch {
 61	        _ => ()
 62	      }
 63	      return
 64	    }
 65	    let temporary = directory +
 66	      "/diagnostic-health." +
 67	      proxy_pid().to_string() +
 68	      ".tmp"
 69	    defer (@fs.remove(temporary) catch { _ => () })
 70	    let snapshot = diagnostic_health_snapshot()
 71	    set_field(snapshot, "runId", Json::string(recording_run_id))
 72	    set_field(
 73	      snapshot,
 74	      "pendingEvents",
 75	      Json::number(diagnostic_pending.length().to_double()),
 76	    )
 77	    set_field(
 78	      snapshot,
 79	      "droppedEvents",
 80	      Json::number(diagnostic_recording_health.dropped.to_double()),
 81	    )
 82	    let mut first = if diagnostic_recording_health.dropped > 0 {
 83	      Some(diagnostic_recording_health.first_dropped)
 84	    } else {
 85	      None
 86	    }
 87	    let mut last = if diagnostic_recording_health.dropped > 0 {
 88	      Some(diagnostic_recording_health.last_dropped)
 89	    } else {
 90	      None
 91	    }
 92	    for pending in diagnostic_pending {
 93	      if first is None || pending.time < first.unwrap() {
 94	        first = Some(pending.time)
 95	      }
 96	      if last is None || pending.time > last.unwrap() {
 97	        last = Some(pending.time)
 98	      }
 99	    }
100	    if first is Some(time) {
101	      set_field(snapshot, "missingFromTime", Json::string(time.to_string()))
102	    }
103	    if last is Some(time) {
104	      set_field(snapshot, "missingThroughTime", Json::string(time.to_string()))
105	    }
106	    if !diagnostic_previous_losses.is_empty() {
107	      set_field(snapshot, "priorLoss", Json::array(diagnostic_previous_losses))
108	    }
109	    @fs.write_file(temporary, snapshot.stringify(), permission=0o600)
110	    @fs.rename(temporary, path, replace=true)
111	  }) catch {
112	    _ => ()
113	  }
114	}
