218	///|
219	fn diagnostic_previous_loss(source : Json) -> Json {
220	  let event = diagnostic_recording_event("degraded", "previous_run_unflushed")
221	  set_field(event, "missingRange", Json::string("unknown"))
222	  if field(source, "affectedRunId") != Some(Json::string("unknown")) &&
223	    field(source, "runId") is Some(Json::String(id)) &&
224	    id.length() > 0 &&
225	    id.length() <= 80 &&
226	    id.iter().all(c => (c >= '0' && c <= '9') || c == '_') {
227	    set_field(event, "runId", Json::string(id))
228	  } else {
229	    set_field(event, "affectedRunId", Json::string("unknown"))
230	  }
231	  for name in ["missingFromTime", "missingThroughTime"] {
232	    if field(source, name) is Some(Json::String(value)) &&
233	      value.length() > 0 &&
234	      value.length() <= 25 &&
235	      value.iter().all(c => c >= '0' && c <= '9') {
236	      set_field(event, name, Json::string(value))
237	    }
238	  }
239	  if field(event, "missingFromTime") is Some(_) &&
240	    field(event, "missingThroughTime") is Some(_) {
241	    set_field(event, "missingRange", Json::string("observed"))
242	  }
243	  let reason = field(source, "previousReason").unwrap_or(
244	    field(source, "reason").unwrap_or(Json::null()),
245	  )
246	  if reason is Json::String(value) &&
247	    [
248	      "lock_busy", "invalid_lock", "invalid_store", "store_timeout", "store_unavailable",
249	      "buffer_full", "protected_values_unavailable", "workspace_recording_unknown",
250	    ].contains(value) {
251	    set_field(event, "previousReason", reason)
252	  }
253	  event
254	}
