299	///|
300	fn diagnostic_json(
301	  value : Json,
302	  environment : Map[String, String],
303	  protected_secrets : Array[String],
304	  truncated : Ref[Bool],
305	  depth : Int32,
306	  stable_activity~ : Bool = false,
307	  secret_states~ : Bool = false,
308	  stable_operation~ : Bool = false,
309	) -> Json {
310	  if depth >= 64 {
311	    truncated.val = true
312	    return Json::string("[nested evidence omitted]")
313	  }
314	  match value {
315	    Json::Object(values) => {
316	      let result = Json::empty_object()
317	      for name, item in values {
318	        let key = name.to_lower().replace_all(old="_", new="")
319	        let safe_name = if (
320	            stable_operation &&
321	            depth == 0 &&
322	            ["operationId", "workspaceId"].contains(name)
323	          ) ||
324	          (
325	            stable_activity &&
326	            [
327	              "schemaVersion", "observedAt", "activity", "reason", "terminals", "chats",
328	              "errors", "worktreeId", "agent", "type", "state", "programState", "sessionId",
329	              "workspaceId", "source", "code", "id", "uid", "context", "provider",
330	              "identityVerified", "vmStatus", "outcome", "evidence", "evidenceTruncated",
331	              "workspaces", "discoveryErrors", "action", "failed", "detailsTruncated",
332	              "error", "autoStop",
333	            ].contains(name)
334	          ) {
335	          name
336	        } else {
337	          diagnostic_text(name, environment~, protected_secrets~)
338	        }
339	        if field(result, safe_name) is Some(_) {
340	          truncated.val = true
341	          continue
342	        }
343	        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
344	          truncated.val = true
345	        }
346	        set_field(
347	          result,
348	          safe_name,
349	          if credential_field(name) || key == "pairingcode" {
350	            if secret_states &&
351	              field(item, "state") is Some(Json::String(state)) &&
352	              ["unset", "empty", "set"].contains(state) {
353	              let masked : Json = { "state": state }
354	              if field(item, "value") is Some(_) {
355	                set_field(masked, "value", Json::string("[redacted]"))
356	              }
357	              if field(item, "truncated") == Some(Json::boolean(true)) {
358	                set_field(masked, "truncated", Json::boolean(true))
359	                truncated.val = true
360	              }
361	              masked
362	            } else {
363	              Json::string("[redacted]")
364	            }
365	          } else if stable_activity &&
366	            name == "activity" &&
367	            (
368	              item == Json::string("idle") ||
369	              item == Json::string("active") ||
370	              item == Json::string("unknown")
371	            ) {
372	            item
373	          } else {
374	            diagnostic_json(
375	              item,
376	              environment,
377	              protected_secrets,
378	              truncated,
379	              depth + 1,
380	              stable_activity~,
381	              secret_states~,
382	              stable_operation~,
383	            )
384	          },
385	        )
386	      }
387	      result
388	    }
389	    Json::Array(values) =>
390	      Json::array(
391	        values.map(item => {
392	          diagnostic_json(
393	            item,
394	            environment,
395	            protected_secrets,
396	            truncated,
397	            depth + 1,
398	            stable_activity~,
399	            secret_states~,
400	            stable_operation~,
401	          )
402	        }),
403	      )
404	    Json::String(text) => {
405	      let safe = diagnostic_text(text, environment~, protected_secrets~)
406	      if safe.has_suffix("\n[error details incomplete or truncated]") {
407	        truncated.val = true
408	      }
409	      Json::string(safe)
410	    }
411	    _ => value
412	  }
413	}
