 987	///|
 988	fn diagnostic_text(
 989	  message : String,
 990	  environment? : Map[String, String],
 991	  omitted~ : Bool = false,
 992	  protected_secrets? : Array[String],
 993	  incomplete_final_line~ : Bool = false,
 994	) -> String {
 995	  let progress = Progress::new("diagnostic-error", environment?)
 996	  if protected_secrets is Some(values) {
 997	    for value in values {
 998	      add_protected_secret(progress.secrets, value)
 999	    }
1000	  }
1001	  progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
1002	  let lines = []
1003	  let mut incomplete = omitted
1004	  let source_lines = message.split("\n").to_array()
1005	  for index in 0..<source_lines.length() {
1006	    let line = source_lines[index]
1007	    if lines.length() == 32 {
1008	      incomplete = true
1009	      ignore(lines.remove(1))
1010	    }
1011	    let truncated = line.length() > 1024
1012	    let bounded = if truncated {
1013	      incomplete = true
1014	      line[:1024].to_owned()
1015	    } else {
1016	      line.to_owned()
1017	    }
1018	    let bounded = if truncated ||
1019	      (incomplete_final_line && index == source_lines.length() - 1) {
1020	      diagnostic_partial_secret(bounded, progress.secrets)
1021	    } else {
1022	      bounded
1023	    }
1024	    match progress.safe_message(bounded) {
1025	      Some(safe) => lines.push(safe)
1026	      None => {
1027	        incomplete = true
1028	        lines.push("[unavailable]")
1029	      }
1030	    }
1031	  }
1032	  if (incomplete || progress.details_truncated) &&
1033	    lines.last() != Some("[error details incomplete or truncated]") {
1034	    lines.push("[error details incomplete or truncated]")
1035	  }
1036	  lines.join("\n")
1037	}
