1039	///|
1040	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
1041	  let chars = text.iter().to_array()
1042	  let mut boundary = chars.length()
1043	  for secret in secrets {
1044	    let value = secret.iter().to_array()
1045	    if value.length() == 0 || text.has_suffix(secret) {
1046	      continue
1047	    }
1048	    let limit = if value.length() - 1 < boundary {
1049	      value.length() - 1
1050	    } else {
1051	      boundary
1052	    }
1053	    if limit == 0 {
1054	      continue
1055	    }
1056	    let prefixes = FixedArray::make(limit, 0)
1057	    let mut matched = 0
1058	    for index in 1..<limit {
1059	      while matched > 0 && value[matched] != value[index] {
1060	        matched = prefixes[matched - 1]
1061	      }
1062	      if value[matched] == value[index] {
1063	        matched += 1
1064	      }
1065	      prefixes[index] = matched
1066	    }
1067	    matched = 0
1068	    for index in 0..<boundary {
1069	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
1070	        matched = prefixes[matched - 1]
1071	      }
1072	      if matched < limit && value[matched] == chars[index] {
1073	        matched += 1
1074	      }
1075	    }
1076	    boundary -= matched
1077	  }
1078	  if boundary == chars.length() {
1079	    text
1080	  } else {
1081	    character_text(chars, 0, boundary) + "[redacted]"
1082	  }
1083	}
