1093	fn diagnostic_add_protected(
1094	  value : String,
1095	  output : String,
1096	  uncertain : Bool,
1097	  destination : Array[String],
1098	  result : DiagnosticProtectedValues,
1099	) -> Unit {
1100	  if value == "" ||
1101	    (
1102	      !output.contains(value) &&
1103	      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
1104	    ) {
1105	    return
1106	  }
1107	  if result.secrets.length() >= 512 {
