1114	///|
1115	fn diagnostic_protected_values(
1116	  value : Json,
1117	  result : DiagnosticProtectedValues,
1118	  output : String,
1119	  uncertain : Bool,
1120	  secret~ : Bool = false,
1121	  depth~ : Int32 = 0,
1122	) -> Unit {
1123	  if result.visited >= 65536 || depth >= 64 {
1124	    result.incomplete = true
1125	    return
1126	  }
1127	  result.visited += 1
1128	  match value {
1129	    Json::String(text) if text != "" && secret => {
1130	      let destination = result.secrets
1131	      diagnostic_add_protected(text, output, uncertain, destination, result)
1132	      for line in text.split("\n") {
1133	        if line != "" && line.length() < text.length() {
1134	          diagnostic_add_protected(
1135	            line.to_owned(),
1136	            output,
1137	            uncertain,
1138	            destination,
1139	            result,
1140	          )
1141	        }
1142	        for word in line.split(" ") {
1143	          for part in word.split("=") {
1144	            if part != "" && part.length() < text.length() {
1145	              diagnostic_add_protected(
1146	                part.to_owned(),
1147	                output,
1148	                uncertain,
1149	                destination,
1150	                result,
1151	              )
1152	            }
1153	          }
1154	        }
1155	      }
1156	      let escaped = Json::string(text).stringify()
1157	      if escaped.length() > 2 {
1158	        let encoded = escaped[1:escaped.length() - 1].to_owned()
1159	        if encoded != text {
1160	          diagnostic_add_protected(
1161	            encoded, output, uncertain, destination, result,
1162	          )
1163	        }
1164	      }
1165	    }
1166	    Json::String(text) if text != "" => {
1167	      let mut next_secret = false
1168	      for word in text.split(" ") {
1169	        let word = word.to_owned()
1170	        if next_secret {
1171	          diagnostic_add_protected(
1172	            word,
1173	            output,
1174	            uncertain,
1175	            result.secrets,
1176	            result,
1177	          )
1178	          next_secret = false
1179	        } else if word.split_once("=") is Some((name, value)) {
1180	          if credential_field(name.to_owned()) {
1181	            diagnostic_add_protected(
1182	              value.to_owned(),
1183	              output,
1184	              uncertain,
1185	              result.secrets,
1186	              result,
1187	            )
1188	          }
1189	        } else if word.has_prefix("-") && credential_field(word) {
1190	          next_secret = true
1191	        }
1192	      }
1193	    }
1194	    Json::Array(values) =>
1195	      for item in values {
1196	        diagnostic_protected_values(
1197	          item,
1198	          result,
1199	          output,
1200	          uncertain,
1201	          secret~,
1202	          depth=depth + 1,
1203	        )
1204	      }
1205	    Json::Object(values) =>
1206	      for name, item in values {
1207	        let key = name.to_lower().replace_all(old="_", new="")
1208	        diagnostic_protected_values(
1209	          item,
1210	          result,
1211	          output,
1212	          uncertain,
1213	          secret=secret || credential_field(name) || key == "pairingcode",
1214	          depth=depth + 1,
1215	        )
1216	      }
1217	    _ => ()
1218	  }
1219	}
