1330	///|
1331	async fn diagnostic_process_output(
1332	  program : String,
1333	  args : Array[String],
1334	  environment~ : Map[String, String],
1335	  cwd? : StringView,
1336	  stdin? : &@process.ProcessInput,
1337	  stdout_limit~ : Int32,
1338	  stderr_limit~ : Int32,
1339	) -> (Int32, Bytes, Bool, Bytes, Bool) {
1340	  let (out, stdout) = @process.read_from_process()
1341	  defer out.close()
1342	  let (err, stderr) = @process.read_from_process()
1343	  defer err.close()
1344	  @async.with_task_group(async fn(group) {
1345	    let child = @process.spawn(
1346	      group,
1347	      program,
1348	      args,
1349	      extra_env=environment,
1350	      inherit_env=false,
1351	      cwd?,
1352	      stdin?,
1353	      stdout~,
1354	      stderr~,
1355	    )
1356	    let output = DiagnosticCapture::new(stdout_limit)
1357	    let errors = DiagnosticCapture::new(stderr_limit)
1358	    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
1359	    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
1360	    let status = child.wait()
1361	    while !output.finished {
1362	      @async.sleep(5)
1363	    }
1364	    wait_diagnostic_captures([errors])
1365	    (
1366	      status,
1367	      output.output.to_bytes(),
1368	      output.truncated,
1369	      errors.output.to_bytes(),
1370	      errors.truncated || !errors.finished,
1371	    )
1372	  })
1373	}
