  1194	    Json::Array(values) =>
  1195	      for item in values {
  1196	        diagnostic_protected_values(
  1197	          item,
  1198	          result,
  1199	          output,
  1200	          uncertain,
  1201	          secret~,
  1202	          depth=depth + 1,
  1203	        )
