  1288	///|
  1289	async fn DiagnosticCapture::read(
  1290	  self : DiagnosticCapture,
  1291	  reader : @process.ReadFromProcess,
  1292	) -> Unit {
  1293	  try {
  1294	    while reader.read_some(max_len=4096) is Some(chunk) {
  1295	      let remaining = self.limit - self.output.length()
  1296	      let count = if chunk.length() < remaining {
  1297	        chunk.length()
  1298	      } else {
  1299	        remaining
  1300	      }
  1301	      if count > 0 {
  1302	        self.output.write_bytes(chunk[:count])
  1303	      }
  1304	      if count < chunk.length() {
  1305	        self.truncated = true
  1306	      }
  1307	    }
  1308	  } catch {
  1309	    error =>
  1310	      if @async.is_being_cancelled() {
  1311	        raise error
  1312	      } else {
  1313	        self.truncated = true
  1314	      }
  1315	  }
  1316	  self.finished = true
  1317	}
