416	async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
417	  let length = if size > 262144L { 262144 } else { size.to_int() }
418	  let bytes = FixedArray::make(length, b'\x00')
419	  let read = file.read_at(bytes, position=size - length.to_int64())
420	  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
421	  let lines = text.split("\n").to_array()
422	  let kept = FixedArray::make(lines.length(), false)
423	  let mut remaining = 65536
424	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
425	    if i == 0 && size > length.to_int64() {
426	      continue
427	    }
428	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
429	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
430	      100
431	    } else {
432	      0
433	    }
434	    let length = lines[i].length() + 1 + overhead
435	    if length <= remaining {
436	      kept[i] = true
437	      remaining -= length
438	    }
439	  }
440	  remaining = 65536
441	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
442	    if kept[i] || (i == 0 && size > length.to_int64()) {
443	      continue
444	    }
445	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
446	    let failed = field(event, "errorType") is Some(_) ||
447	      (match field(event, "status") {
448	        Some(Json::String(status)) =>
449	          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
450	            status,
451	          )
452	        _ => false
453	      })
454	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
455	      100
456	    } else {
457	      0
458	    }
459	    let length = lines[i].length() + 1 + overhead
460	    if failed && length <= remaining {
461	      kept[i] = true
462	      remaining -= length
463	    }
464	  }
465	  let dropped_runs : Map[String, Bool] = Map([])
466	  for i in 0..<(lines.length() - 1) {
467	    if !kept[i] {
468	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
469	      if field(event, "runId") is Some(Json::String(id)) {
470	        dropped_runs.set(id, true)
471	      }
472	    }
473	  }
474	  let result = @buffer.Buffer(size_hint=131072)
475	  for i in 0..<lines.length() {
476	    if kept[i] {
477	      let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
478	      if field(event, "runId") is Some(Json::String(id)) {
479	        set_field(
480	          event,
481	          "runCompleteness",
482	          Json::string(
483	            if dropped_runs.contains(id) ||
484	              field(event, "runCompleteness") == Some(Json::string("partial")) {
485	              "partial"
486	            } else {
487	              "unknown"
488	            },
489	          ),
490	        )
491	        set_field(event, "runMissingReason", Json::string("retention_limit"))
492	        result.write_string_utf8(event.stringify() + "\n")
493	      } else {
494	        result.write_string_utf8(lines[i].to_owned() + "\n")
495	      }
496	    }
497	  }
498	  @utf8.decode_lossy(result.to_bytes())
499	}
