 14	///|
 15	async fn settings_executable(pid : Int32) -> String {
 16	  if @async.platform is Linux {
 17	    return @fs.realpath("/proc/\{pid}/exe")
 18	  }
 19	  let buffer = Bytes::make(4096, 0)
 20	  let length = process_executable(pid, buffer, buffer.length())
 21	  guard length > 0 && length < buffer.length() else {
 22	    raise AdapterError("Cannot locate the running host Orca executable")
 23	  }
 24	  @utf8.decode(buffer[:length])
 25	}
