416	///|
417	async fn Progress::line(
418	  self : Progress,
419	  line : String,
420	  statuses~ : Bool,
421	  messages~ : Bool,
422	) -> Unit {
423	  if line.trim() == "" {
424	    return
425	  }
426	  let event = @json.parse(line) catch { _ => Json::null() }
427	  if field(event, "kind") == Some(Json::string("status")) {
428	    if field(event, "state") == Some(Json::string("failed")) &&
429	      field(event, "error") is Some(error) {
430	      for name in ["message", "hint"] {
431	        if field(error, name) is Some(Json::String(text)) {
432	          self.message(
433	            text,
434	            debug=false,
435	            warning=true,
436	            emit=messages || statuses,
437	          )
438	        }
439	      }
440	    }
441	    if statuses || messages {
442	      self.status(event)
443	    }
444	    return
445	  }
446	  // Result envelopes and arbitrary structured responses are never log text.
447	  if field(event, "kind") == Some(Json::string("result")) {
448	    return
449	  }
450	  if event is Json::Object(_) {
451	    let kind = field(event, "kind")
452	    guard kind == None ||
453	      kind == Some(Json::string("log")) ||
454	      kind == Some(Json::string("error")) else {
455	      return
456	    }
457	    let message = match field(event, "msg") {
458	      Some(value) => Some(value)
459	      None =>
460	        match field(event, "message") {
461	          Some(value) => Some(value)
462	          None =>
463	            match field(event, "error") {
464	              Some(Json::Object(_) as value) => field(value, "message")
465	              value => value
466	            }
467	        }
468	    }
469	    guard message is Some(Json::String(text)) else { return }
470	    let level = field(event, "level")
471	    self.message(
472	      text,
473	      debug=level == Some(Json::string("debug")) ||
474	        level == Some(Json::string("trace")),
475	      warning=kind == Some(Json::string("error")) ||
476	        level == Some(Json::string("warn")) ||
477	        level == Some(Json::string("error")),
478	      emit=messages || (statuses && kind != None),
479	    )
480	  } else {
481	    if event != Json::null() {
482	      return
483	    }
484	    // Malformed JSON and binary output are not a safe free-text fallback.
485	    let text = line.trim().to_owned()
486	    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
487	      self.message(text, debug=false, warning=true, emit=messages)
488	      return
489	    }
490	    if text.has_prefix("{") || text.has_prefix("[") {
491	      self.details_truncated = true
492	      return
493	    }
494	    self.message(
495	      text,
496	      debug=text.contains(" DEBUG ") ||
497	        text.contains(" TRACE ") ||
498	        text.has_prefix("DEBUG ") ||
499	        text.has_prefix("TRACE "),
500	      warning=text.contains(" WARN ") ||
501	        text.contains(" ERROR ") ||
502	        text.has_prefix("WARN ") ||
503	        text.has_prefix("ERROR "),
504	      emit=messages,
505	    )
506	  }
507	}
