 50	///|
 51	fn credential_word(c : Char) -> Bool {
 52	  (c >= 'a' && c <= 'z') ||
 53	  (c >= 'A' && c <= 'Z') ||
 54	  (c >= '0' && c <= '9') ||
 55	  c == '_' ||
 56	  c == '-'
 57	}
 58	
 59	///|
 60	fn credential_space(c : Char) -> Bool {
 61	  c == ' ' || c == '\t'
 62	}
 63	
 64	///|
 65	fn credential_end(c : Char) -> Bool {
 66	  credential_space(c) ||
 67	  [',', ';', '&', '#', '"', '\'', '}', ']', '<', '>'].contains(c)
 68	}
 69	
 70	///|
 71	fn character_text(chars : Array[Char], start : Int32, end : Int32) -> String {
 72	  let buffer = @buffer.Buffer(size_hint=end - start)
 73	  for i in start..<end {
 74	    buffer.write_char_utf8(chars[i])
 75	  }
 76	  @utf8.decode_lossy(buffer.to_bytes())
 77	}
 78	
 79	///|
 80	fn credential_hex(c : Char) -> Int32? {
 81	  match c {
 82	    '0'..<='9' => Some(c.to_int() - '0'.to_int())
 83	    'a'..<='f' => Some(c.to_int() - 'a'.to_int() + 10)
 84	    'A'..<='F' => Some(c.to_int() - 'A'.to_int() + 10)
 85	    _ => None
 86	  }
 87	}
 88	
 89	///|
 90	fn credential_parameter(name : String) -> String {
 91	  let chars = name.iter().to_array()
 92	  let buffer = @buffer.Buffer(size_hint=name.length())
 93	  let mut i = 0
 94	  while i < chars.length() {
 95	    if chars[i] == '%' &&
 96	      i + 2 < chars.length() &&
 97	      credential_hex(chars[i + 1]) is Some(hi) &&
 98	      credential_hex(chars[i + 2]) is Some(lo) {
 99	      buffer.write_char_utf8((hi * 16 + lo).unsafe_to_char())
100	      i += 3
101	    } else {
102	      buffer.write_char_utf8(chars[i])
103	      i += 1
104	    }
105	  }
106	  @utf8.decode_lossy(buffer.to_bytes())
107	}
