282	///|
283	fn Progress::safe_message(self : Progress, text : String) -> String? {
284	  guard terminal_text(text) is Some(text) else { return None }
285	  let lower = text.to_lower()
286	  if lower.contains("-----begin ") && lower.contains("private key-----") {
287	    self.private_key = REDACTED ")
288	    return Some("[private key redacted]")
289	  }
290	  if self.private_key {
291	    if lower.contains("-----end ") && lower.contains("private key-----") {
292	      self.private_key = false
293	    }
294	    return None
295	  }
296	  let known = redact_known_values(text, self.secrets)
297	  let mut safe = redact_known_values(redact_credentials(known), self.secrets)
298	  if safe.length() > 1024 {
299	    safe = safe[:1024].to_owned() + "… [truncated]"
300	    self.details_truncated = true

