    state = {'adapterVersion': 1, 'workspaceId': 'test', 'workspaceUid': 'uid', 'user': 'developer', 'command': [fake], 'devsyEnv': {}, 'tunnelDirectory': root + '/tunnel'}
    payload = {'schemaVersion': 1, 'recipeResult': {'userData': state}}
    env = {'HOME': root, 'XDG_STATE_HOME': root + '/state', 'PATH': '/usr/bin:/bin'}
